func GetBuilding(t building.Type) (BuildingType, bool) {
	if ruin, ok := RuinSpecs[t]; ok {
		return ruin, true
	}
	ensureBuildingBalance()
	item, ok := Buildings[t]
	return item, ok
}

func FirstLevelBuildings() []BuildingType {
	ensureBuildingBalance()
	items := make([]BuildingType, 0, len(firstLevelTypes))
	for _, t := range firstLevelTypes {
		item, _ := GetBuilding(t)
		items = append(items, item)
	}
	return items
}

func AllBuildings() []BuildingType {
	ensureBuildingBalance()
	items := make([]BuildingType, 0, len(Buildings))
	for _, item := range Buildings {
		items = append(items, item)
	}
	sort.Slice(items, func(i, j int) bool { return items[i].Type < items[j].Type })
	return items
}
